	hooks, err := json.Marshal(map[string]any{"hooks": map[string]any{"SessionEnd": []any{map[string]any{
		"hooks": []any{map[string]any{"type": "command", "command": "sh hook.sh", "async": true}}}}}})
	require.NoError(t, err)
	r := execMock(t, scenario{
