		Files:     map[string]string{"hook.sh": `cat >/dev/null; sleep 0.5; echo ended >"$(dirname "$HOOK_LOG")/session-end-done"`},
		Script:    callThenResult, Prompt: "go", Env: withCalls(t),
	})
	require.Equal(t, 0, r.Code, r.Stderr)
