	s := unmodeled.ReplaceAllString(stderr, "")
	s = banner.ReplaceAllString(s, "$1: <X>")
	s = command.ReplaceAllString(s, "<COMMAND>")
	s = duration.ReplaceAllString(s, "in Nms:")
	return tokens.ReplaceAllString(s, "tokens used\n<N>")
